import{_ as t,o as a,c as r,an as n}from"./chunks/framework.Bftm1s3B.js";const i="/Kraken.jl/v0.3.0/assets/refinement_showcase.1rk8wsuN.png",u=JSON.parse('{"title":"Refinement showcase — honest status (v0.1.0)","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks/refinement_showcase.md","filePath":"benchmarks/refinement_showcase.md","lastUpdated":null}'),s={name:"benchmarks/refinement_showcase.md"};function o(l,e,c,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="Refinement-showcase-—-honest-status-v0.1.0" tabindex="-1">Refinement showcase — honest status (v0.1.0) <a class="header-anchor" href="#Refinement-showcase-—-honest-status-v0.1.0" aria-label="Permalink to &quot;Refinement showcase — honest status (v0.1.0) {#Refinement-showcase-—-honest-status-v0.1.0}&quot;">​</a></h1><p>This page reports where patch-based grid refinement stands in Kraken.jl v0.1.0. <strong>Refinement is validated for stability</strong>: the Filippova–Hänel (FH) rescaling, temporal sub-cycling and restriction all work across CPU, CUDA and Metal backends, and the 2D tests pass. A <strong>cost-vs-accuracy win on integrated quantities</strong> (Nu for natural convection, Cd for cylinder flow) is <strong>not yet demonstrated</strong> and is tracked as a v0.2.0 item.</p><p><img src="'+i+`" alt=""></p><h2 id="What-works-in-v0.1.0" tabindex="-1">What works in v0.1.0 <a class="header-anchor" href="#What-works-in-v0.1.0" aria-label="Permalink to &quot;What works in v0.1.0 {#What-works-in-v0.1.0}&quot;">​</a></h2><ul><li><p><code>Refine { region = [...], ratio = r }</code> blocks in <code>.krk</code> files automatically route to the patch runner; no custom driver is needed.</p></li><li><p><strong>Two symmetric wall patches</strong> are instantiated in the natural convection driver (<code>run_natural_convection_refined_2d</code>): one at the hot wall and one at the cold wall, each with physical width <code>wall_fraction · L</code> and the full vertical extent of the cavity.</p></li><li><p>Patch ghost cells use FH f_neq rescaling for flow and bilinear/temporal interpolation for temperature; restriction is a block-average of ratio² fine cells back to each coarse cell.</p></li><li><p>2D cavity flow with central patch, 2D natural convection with wall patches and 3D refined conduction all run stably on CPU and GPU.</p></li></ul><h2 id="What-does-not-yet-showcase-a-win" tabindex="-1">What does not yet showcase a win <a class="header-anchor" href="#What-does-not-yet-showcase-a-win" aria-label="Permalink to &quot;What does not yet showcase a win {#What-does-not-yet-showcase-a-win}&quot;">​</a></h2><p>Results on Metal (Apple M3 Max, Float32) at Ra = 10³ with wall_fraction = 0.20, ratio = 2, after the GPU-sync fix (see below).</p><table tabindex="0"><thead><tr><th style="text-align:right;">Mode</th><th style="text-align:right;">N_base</th><th style="text-align:right;">Nu</th><th style="text-align:right;">error</th><th style="text-align:right;">wall-time</th><th style="text-align:right;">steps/s</th></tr></thead><tbody><tr><td style="text-align:right;">uniform</td><td style="text-align:right;">64</td><td style="text-align:right;">1.1419</td><td style="text-align:right;">2.13 %</td><td style="text-align:right;">6.0 s</td><td style="text-align:right;">10 182</td></tr><tr><td style="text-align:right;">uniform</td><td style="text-align:right;">128</td><td style="text-align:right;">1.1285</td><td style="text-align:right;">0.94 %</td><td style="text-align:right;">25.6 s</td><td style="text-align:right;">9 601</td></tr><tr><td style="text-align:right;">refined</td><td style="text-align:right;">64</td><td style="text-align:right;">1.1880</td><td style="text-align:right;">6.26 %</td><td style="text-align:right;">506 s</td><td style="text-align:right;">121</td></tr><tr><td style="text-align:right;">refined</td><td style="text-align:right;">96</td><td style="text-align:right;">1.2161</td><td style="text-align:right;">8.77 %</td><td style="text-align:right;">1 202 s</td><td style="text-align:right;">115</td></tr><tr><td style="text-align:right;">refined</td><td style="text-align:right;">128</td><td style="text-align:right;">1.2086</td><td style="text-align:right;">8.10 %</td><td style="text-align:right;">2 375 s</td><td style="text-align:right;">103</td></tr></tbody></table><p>Two independent problems stand out:</p><ol><li><p><strong>Throughput gap</strong>: even with the sync fix, refined runs at ~110 steps/s while uniform runs at ~10 000 steps/s — a 90 × gap due to many small kernel launches per coarse step (ghost fills, stream, BC, collide, macro, restrict, copyto!s) versus one fused kernel for the uniform case.</p></li><li><p><strong>Accuracy plateau with a positive bias</strong>: the refined error does not improve as <code>N_base</code> grows; it actually gets worse (6.26 → 8.77 %) before stabilising near 8 %. This is a zeroth-order bias at the patch interface, not a convergence problem.</p></li></ol><h2 id="Perf-bug-fixed-2026-04-14" tabindex="-1">Perf bug fixed (2026-04-14) <a class="header-anchor" href="#Perf-bug-fixed-2026-04-14" aria-label="Permalink to &quot;Perf bug fixed (2026-04-14) {#Perf-bug-fixed-2026-04-14}&quot;">​</a></h2><p>Until commit <code>&lt;sync-fix&gt;</code> every kernel wrapper ended with <code>KernelAbstractions.synchronize(backend)</code>. That is fine when the CPU driver launches one large kernel per time step (the uniform case: one <code>fused_natconv_step!</code>), but it is disastrous inside the sub-cycled refined step where ~50 wrappers are called per coarse step — each blocking the CPU on GPU completion.</p><p>The fix removed the unconditional <code>KernelAbstractions.synchronize</code> calls from 134 kernel wrappers in <code>src/kernels/</code> and <code>src/refinement/</code>, and flipped the default of the opt-in <code>sync</code> keyword on <code>stream_2d!</code>, <code>collide_2d!</code> and <code>compute_macroscopic_2d!</code> to <code>false</code>. KernelAbstractions already serialises kernels submitted on the same stream, so intermediate syncs are redundant for GPU-only pipelines; the only natural sync point is the final <code>Array(...)</code> copy back to host in the top-level driver.</p><p>Measured impact on Metal Float32:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Mode</th><th style="text-align:right;">N_base</th><th style="text-align:right;">Before</th><th style="text-align:right;">After</th><th style="text-align:right;">Speedup</th></tr></thead><tbody><tr><td style="text-align:right;">uniform</td><td style="text-align:right;">64</td><td style="text-align:right;">?</td><td style="text-align:right;">10 182 sps</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;">uniform</td><td style="text-align:right;">128</td><td style="text-align:right;">1 984 sps</td><td style="text-align:right;">9 601 sps</td><td style="text-align:right;">4.8 ×</td></tr><tr><td style="text-align:right;">refined</td><td style="text-align:right;">64</td><td style="text-align:right;">40 sps</td><td style="text-align:right;">121 sps</td><td style="text-align:right;">3.0 ×</td></tr></tbody></table><p>The uniform case ran 128 ²= 16 384 cells in one fused kernel so each step was already launch-bound; removing the per-step sync converts wall-time almost entirely to compute. The refined case still has many small launches, so the speedup is smaller but real.</p><h2 id="Root-causes-accuracy" tabindex="-1">Root causes (accuracy) <a class="header-anchor" href="#Root-causes-accuracy" aria-label="Permalink to &quot;Root causes (accuracy) {#Root-causes-accuracy}&quot;">​</a></h2><ol><li><p><strong>Thermal ghost fill uses no FH rescaling.</strong> The thermal patch interpolates coarse temperature populations bilinearly in space and linearly in time, without non-equilibrium rescaling (see <code>src/refinement/thermal_refinement.jl</code>). This breaks strict conservation of the heat flux across the patch interface.</p></li><li><p><strong>Boussinesq feedback at the patch boundary.</strong> The buoyancy force depends on the local temperature, so any interpolation error in the ghost cells feeds back into the flow, which in turn biases the temperature gradient at the hot wall — i.e. exactly the quantity that sets Nu.</p></li><li><p><strong>Bulk runs coarse.</strong> With <code>wall_fraction = 0.2</code> and <code>ratio = 2</code>, only 20 % of the domain near each wall is refined; the central recirculation is at the base resolution. For Ra = 10⁵ the core contributes as much to the Nu budget as the boundary layer, so refining only the walls cannot reach the accuracy of a uniform fine grid.</p></li><li><p><strong>Per-step cost is dominated by the patch.</strong> Each coarse step triggers <code>ratio</code> fine sub-steps on each patch. At <code>ratio = 2</code> and two wall patches covering 20 % of the domain, the sub-cycled patch work is <code>2 · 0.2 · L² · ratio = 0.8 · L²</code> per coarse step, on top of <code>L²</code> for the bulk. The patch contribution dominates the 10 × slowdown observed.</p></li></ol><h2 id="Design-constraint-v0.1.0" tabindex="-1">Design constraint (v0.1.0) <a class="header-anchor" href="#Design-constraint-v0.1.0" aria-label="Permalink to &quot;Design constraint (v0.1.0) {#Design-constraint-v0.1.0}&quot;">​</a></h2><p>Refinement is <strong>generic</strong>: it must work for any <code>.krk</code> setup, not be hand-coded per benchmark. The user&#39;s BCs reach the patch sub-step as <code>bc_*_patch_fns</code> closures, which cannot be marshalled into a GPU kernel. That is why the patch sub-step currently issues many small kernels (~8–10 per sub-step) instead of a single fused kernel: the closure pattern preserves genericity at the cost of launch overhead.</p><p>A case-specific fused kernel (e.g. <code>fused_natconv_patch_step!</code>) was prototyped and measured on Metal M3 Max: it recovered ~1.2× over the unfused path for Ra = 10³ natconv, but locked the refinement code to a specific BC template. The prototype was rejected for v0.1.0 and the generic closure-based path kept.</p><h2 id="Where-refinement-should-win-planned-for-v0.2.0" tabindex="-1">Where refinement should win (planned for v0.2.0) <a class="header-anchor" href="#Where-refinement-should-win-planned-for-v0.2.0" aria-label="Permalink to &quot;Where refinement should win (planned for v0.2.0) {#Where-refinement-should-win-planned-for-v0.2.0}&quot;">​</a></h2><ol><li><p><strong>Compile-time BC tags</strong> instead of closures, so a single templated kernel can fuse stream + BC + macro + collide while remaining generic.</p></li><li><p><strong>FH-rescaled thermal populations.</strong> The FH factor that works for flow (α = ratio) <em>overshoots</em> for the passive scalar on De Vahl Davis (measured Nu = 0.6 vs ref 1.118). The correct scaling for thermal passive scalar remains open.</p></li><li><p><strong>Cylinder Cd with FH-rescaled MEA.</strong> Momentum-exchange drag on a refined patch around a cylinder requires rescaling the non-equilibrium populations before accumulating the boundary-link sum (Lagrava et al. 2012). Scaffolding is in <a href="https://github.com/lauguimel/Kraken.jl/blob/main/benchmarks/convergence_cylinder_refinement.jl" target="_blank" rel="noreferrer"><code>benchmarks/convergence_cylinder_refinement.jl</code></a>, with diagnostic hooks <code>patch_diag_fns</code> and <code>coarse_diag_fn</code> already added to <code>advance_refined_step!</code>.</p></li><li><p><strong>Localised-feature benchmarks</strong> where the bulk is trivial: impinging jet on a heated plate, shear layer, contraction.</p></li><li><p><strong>Adaptive refinement</strong> (wavelet error estimator) rather than user-specified patches — the Basilisk-style approach that gives the large speed-ups observed in the AMR literature.</p></li></ol><h2 id="How-to-reproduce" tabindex="-1">How to reproduce <a class="header-anchor" href="#How-to-reproduce" aria-label="Permalink to &quot;How to reproduce {#How-to-reproduce}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the sweep (CPU by default; GPU via backend kwarg).</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmarks/convergence_natconv_refinement.jl</span></span></code></pre></div><p>The script writes a CSV to <code>benchmarks/results/</code> and prints a table with Nu, error, wall-time and <code>cell·steps</code> for each configuration. The cylinder scaffolding lives in <a href="https://github.com/lauguimel/Kraken.jl/blob/main/benchmarks/convergence_cylinder_refinement.jl" target="_blank" rel="noreferrer"><code>convergence_cylinder_refinement.jl</code></a> and documents the FH-force-rescaling TODO inline.</p><h2 id="Cross-reference" tabindex="-1">Cross-reference <a class="header-anchor" href="#Cross-reference" aria-label="Permalink to &quot;Cross-reference {#Cross-reference}&quot;">​</a></h2><ul><li><p>Theory: <a href="./../theory/18_grid_refinement">Grid refinement</a></p></li><li><p>Driver: <code>run_natural_convection_refined_2d</code> (<a href="https://github.com/lauguimel/Kraken.jl/blob/main/src/drivers/thermal.jl" target="_blank" rel="noreferrer"><code>drivers/thermal.jl</code></a>)</p></li><li><p>Sanity check: the <code>_check_thermal!</code> routine warns when <code>N_eff &lt; 3·Ra^(1/4)</code> (see <a href="./../krk/sanity">Sanity</a>).</p></li><li><p>Capabilities status: <a href="./../capabilities">Capabilities §4</a>.</p></li></ul>`,28)])])}const f=t(s,[["render",o]]);export{u as __pageData,f as default};
